                    startX: x,
                    startY: y,
                    endX: x,
                    endY: y,
                    translateX: -this._core.store.state.translateX / divider,
                    translateY: -this._core.store.state.translateY / divider,
                    scale: lockScale ? 1 : viewportScale,
                    stroke: this.color,
                    strokeWidth: this.size,
                    opacity: this.opacity,
                    arrows: this.arrows,
