            // timestamp format: YYYY-MM-DDTHH-mm-ss-sssZ, clearing colons/dots for safe filename
            const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
            const filename = `${activeWorkspaceName}-${timestamp}.png`;
